-- Update menu-name i18n keys to semantic menu IDs.
ALTER TABLE sys_i18n_dict MODIFY COLUMN dict_id varchar(100);
UPDATE sys_i18n_dict SET dict_id = CONCAT(lang_tag, '@', lang_key);

DELETE FROM sys_i18n_dict WHERE lang_key like 'MENU.NAME.%';



